// Código do nó Code "Uma linha por livro", no modo Run Once for All Items.
// É o mesmo texto que está dentro de monitor.json: aqui fica mais fácil de ler.
//
// Entra: um item do nó "Tirar os livros", com quatro listas do mesmo tamanho
// (titulo, preco, disponibilidade, endereco).
// Sai: um item por livro, com as cinco colunas da rodada.
const LOJA = 'https://books.toscrape.com/';
// $now segue o fuso do fluxo (Settings > Timezone). O Date() do JavaScript não segue.
const rodada = $now.toFormat('yyyy-MM-dd');
const linhas = [];
for (const item of $input.all()) {
  const { titulo = [], preco = [], disponibilidade = [], endereco = [] } = item.json;
  const tamanhos = [preco.length, disponibilidade.length, endereco.length];
  if (tamanhos.some((n) => n !== titulo.length)) {
    throw new Error(
      `As listas vieram com tamanhos diferentes: ${titulo.length} títulos, ${preco.length} preços, ` +
        `${disponibilidade.length} disponibilidades e ${endereco.length} endereços. Veja os seletores do nó "Tirar os livros".`,
    );
  }
  titulo.forEach((t, i) => {
    // "£51.77" vira "51.77". Se a página vier com o símbolo trocado, o número continua certo.
    const numero = String(preco[i]).match(/\d+(\.\d+)?/);
    linhas.push({
      json: {
        rodada,
        url: endereco[i].startsWith('http') ? endereco[i] : LOJA + endereco[i].replace(/^\.?\//, ''),
        titulo: t,
        preco: numero ? Number(numero[0]).toFixed(2) : '',
        disponivel: /in stock/i.test(disponibilidade[i]) ? 'sim' : 'nao',
      },
    });
  });
}
return linhas;

// Código do nó Code "Comparar com a anterior", no modo Run Once for All Items.
// É o mesmo texto que está dentro de monitor.json.
//
// Entra: as linhas da rodada anterior, lidas do arquivo pelo nó "CSV para itens".
// Do arquivo, tudo chega como texto: "50.10", "sim".
// Lê também a rodada de hoje, direto no nó "Uma linha por livro".
// Sai: um item só, com o resumo e a lista do que mudou. O arquivo CSV da rodada
// de hoje vai junto, para os dois nós que gravam.
const hoje = $('Uma linha por livro').all().map((item) => item.json);
const antes = $input.all().map((item) => item.json);
const antesPorUrl = new Map(antes.map((linha) => [linha.url, linha]));

const mudancas = [];
for (const livro of hoje) {
  const velho = antesPorUrl.get(livro.url);
  // Livro que não estava na rodada anterior: essa versão do monitor não avisa.
  if (!velho) continue;
  // Compara como número: "50.1" e "50.10" são o mesmo preço.
  if (Number(velho.preco) !== Number(livro.preco)) {
    mudancas.push({ url: livro.url, titulo: livro.titulo, tipo: 'preco', antes: velho.preco, depois: livro.preco });
  }
  if (velho.disponivel !== livro.disponivel) {
    mudancas.push({
      url: livro.url, titulo: livro.titulo, tipo: 'disponibilidade', antes: velho.disponivel, depois: livro.disponivel,
    });
  }
}

return [
  {
    json: {
      rodada: hoje.length ? hoje[0].rodada : '',
      rodada_anterior: antes.length ? antes[0].rodada : '',
      livros_hoje: hoje.length,
      livros_antes: antes.length,
      mudancas,
    },
    binary: $('Rodada de hoje em CSV').first().binary,
  },
];

// Código do nó Code "Montar o aviso", no modo Run Once for All Items.
// É o mesmo texto que está dentro de monitor.json.
//
// Só roda quando o If "Mudou algo?" sai pelo verdadeiro.
// Entra: o resumo do nó "Comparar com a anterior" (os nós de gravar passam o resumo adiante).
// Sai: um item com o assunto, o texto do aviso e a lista do que mudou.
const r = $input.first().json;
const linhas = r.mudancas.map((m) => {
  if (m.tipo === 'preco') {
    const rumo = Number(m.depois) < Number(m.antes) ? 'caiu' : 'subiu';
    return `${m.titulo}: o preço ${rumo} de £${m.antes} para £${m.depois}`;
  }
  return `${m.titulo}: ${m.depois === 'sim' ? 'voltou ao estoque' : 'ficou sem estoque'}`;
});
return [
  {
    json: {
      assunto: `Monitor de preço: ${r.mudancas.length} mudança(s) na rodada de ${r.rodada}`,
      texto: [`Comparei ${r.livros_hoje} livros com a rodada de ${r.rodada_anterior}.`, ...linhas.map((l) => `- ${l}`)].join('\n'),
      mudancas: r.mudancas,
    },
  },
];

// Código do nó Code "Checar a saúde da rodada", no modo Run Once for All Items.
// É o mesmo texto que está dentro de monitor-com-trava.json.
//
// Entra: um item do nó "Tirar os livros", com quatro listas (titulo, preco,
// disponibilidade, endereco). O nó HTML sempre retorna esse item, mesmo quando
// os seletores não acham nada: aí as listas vêm vazias.
// Sai: um item só, com a rodada em "linhas" e a lista "problemas".
// Lista vazia: a rodada está boa. Qualquer problema: o fluxo não grava e avisa.

// As duas regras de saúde. Os números são decisão de quem usa o monitor.
const CONTAGEM_MINIMA = 16; // a página 1 da loja traz 20 livros
const MAX_VAZIOS = 0.1; // até 10% de um campo vazio ainda passa

const LOJA = 'https://books.toscrape.com/';
const rodada = $now.toFormat('yyyy-MM-dd');
const lista = (v) => (Array.isArray(v) ? v : v == null || v === '' ? [] : [v]);
const { titulo, preco, disponibilidade, endereco } = $input.first().json;
const listas = {
  titulo: lista(titulo),
  preco: lista(preco),
  disponibilidade: lista(disponibilidade),
  endereco: lista(endereco),
};
const total = Math.max(...Object.values(listas).map((l) => l.length));

// Só aceita o formato que a loja usa. O que não reconhece fica vazio,
// para a regra de vazios ver. "£51.77" vira "51.77"; "51,77 €" fica vazio.
const lerPreco = (texto) => {
  const m = String(texto ?? '').match(/£\s*(\d+\.\d{2})/);
  return m ? m[1] : '';
};
// "In stock" vira sim, "Out of stock" vira nao. Texto novo fica vazio,
// em vez de virar "nao" e aparecer como livro sem estoque.
const lerEstoque = (texto) => {
  const t = String(texto ?? '');
  if (/out of stock/i.test(t)) return 'nao';
  if (/\bin stock\b/i.test(t)) return 'sim';
  return '';
};
const lerEndereco = (href) => {
  const h = String(href ?? '').trim();
  if (!h) return '';
  return h.startsWith('http') ? h : LOJA + h.replace(/^\.?\//, '');
};

const linhas = [];
for (let i = 0; i < total; i++) {
  linhas.push({
    rodada,
    url: lerEndereco(listas.endereco[i]),
    titulo: String(listas.titulo[i] ?? '').trim(),
    preco: lerPreco(listas.preco[i]),
    disponivel: lerEstoque(listas.disponibilidade[i]),
  });
}

const problemas = [];
// Regra 1: contagem mínima.
if (total < CONTAGEM_MINIMA) {
  problemas.push({ regra: 'contagem', detalhe: `${total} livros na página; o mínimo é ${CONTAGEM_MINIMA}` });
}
// Listas de tamanhos diferentes: um campo sumiu de algum livro, e os
// valores dos livros seguintes ficariam no livro errado.
const tamanhos = Object.values(listas).map((l) => l.length);
if (total > 0 && tamanhos.some((n) => n !== total)) {
  problemas.push({
    regra: 'listas',
    detalhe:
      `as listas vieram com tamanhos diferentes: ${listas.titulo.length} títulos, ${listas.preco.length} preços, ` +
      `${listas.disponibilidade.length} disponibilidades e ${listas.endereco.length} endereços`,
  });
}
// Regra 2: percentual de campos vazios.
if (total > 0) {
  const nomes = { url: 'endereço', titulo: 'título', preco: 'preço', disponivel: 'disponibilidade' };
  for (const campo of Object.keys(nomes)) {
    const vazios = linhas.filter((l) => l[campo] === '').length;
    if (vazios / total > MAX_VAZIOS) {
      problemas.push({
        regra: 'vazios',
        campo,
        detalhe: `${vazios} de ${total} livros sem ${nomes[campo]} (${Math.round((100 * vazios) / total)}%)`,
      });
    }
  }
}

return [{ json: { rodada, total, problemas, linhas } }];

// Código do nó Code "Montar o alerta de quebra", no modo Run Once for All Items.
// É o mesmo texto que está dentro de monitor-com-trava.json.
//
// Só roda quando o If "A raspagem quebrou?" sai pelo verdadeiro.
// Entra: o item com "rodada" e "problemas".
// Sai: um item com o assunto, o texto do alerta e a lista de problemas.
const r = $input.first().json;
return [
  {
    json: {
      assunto: `Monitor de preço: a raspagem quebrou na rodada de ${r.rodada}`,
      texto: [
        'Nada foi gravado. A rodada anterior continua valendo.',
        ...r.problemas.map((p) => `- ${p.detalhe}`),
        'Abra a página da loja e veja se o layout mudou antes de mexer no fluxo.',
      ].join('\n'),
      problemas: r.problemas,
    },
  },
];
